pipeline {
    agent { label 'linux && java21' }
    tools {
        jdk 'JDK 21'
        maven 'Maven 3.9'
    }
    parameters {
        choice(name: 'TARGET_ENV', choices: ['qa', 'staging'], description: 'Deployment target')
    }
    stages {
        stage('Checkout') { steps { checkout scm } }
        stage('Build') { steps { sh 'mvn -B clean package -DskipTests' } }
        stage('Test') {
            parallel {
                stage('Unit') { steps { sh 'mvn -B test' } }
                stage('Integration') { steps { sh 'mvn -B verify -Pintegration' } }
            }
        }
        stage('Package') { steps { archiveArtifacts artifacts: 'target/*.jar', fingerprint: true } }
        stage('Deploy QA') { steps { echo "Deploying to ${params.TARGET_ENV}" } }
    }
    post {
        always { junit 'target/surefire-reports/*.xml' }
    }
}
